import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";
import {
  haeyoomSmsHeader,
  smsServiceLabelEn,
  stripPromoFromCustomServiceNameForConfirmationSms,
  stripPromoFromConfirmationSmsServiceLabel,
} from "./sms-labels.ts";

// Comment: Keep message helpers aligned with `lib/twilio.ts` (confirmation template).
const WEEKDAY_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"] as const;

function formatReminderAppointmentLine(bookingDate: string, bookingTime: string | null): string {
  try {
    const [year, month, day] = bookingDate.split("-").map((v) => Number(v));
    const [hStr, mStr] = (bookingTime ?? "00:00:00").split(":");
    const hour = Number(hStr);
    const minute = Number(mStr);
    const date = new Date(Date.UTC(year, month - 1, day, hour, minute));
    const dd = String(day).padStart(2, "0");
    const mm = String(month).padStart(2, "0");
    const dow = WEEKDAY_SHORT[date.getUTCDay()];
    let displayHour = date.getUTCHours();
    const displayMinute = String(date.getUTCMinutes()).padStart(2, "0");
    const ampm = displayHour >= 12 ? "pm" : "am";
    displayHour = displayHour % 12;
    if (displayHour === 0) displayHour = 12;
    return `${dd}/${mm} (${dow}) ${displayHour}:${displayMinute}${ampm}`;
  } catch {
    return `${bookingDate} ${bookingTime ?? ""}`.trim();
  }
}

function isValidAuMobilePhone(phoneRaw: string | null | undefined): boolean {
  const digits = String(phoneRaw || "").replace(/[^0-9]/g, "");
  return /^04\d{8}$/.test(digits);
}

// Comment: Keep in sync with lib/booking-confirmation-sms.ts `buildBookingConfirmationSmsBody`.
function formatAuPhoneForSmsDisplay(raw: string | null | undefined): string | null {
  const s = String(raw ?? "").trim();
  if (!s) return null;
  const digits = s.replace(/\D/g, "");
  let local = digits;
  if (local.startsWith("61") && local.length >= 9) {
    local = `0${local.slice(2)}`;
  }
  if (local.startsWith("0") && local.length === 10) {
    return `${local.slice(0, 4)} ${local.slice(4, 7)} ${local.slice(7)}`;
  }
  if (local.length >= 8) {
    return s;
  }
  return s;
}

function buildBookingConfirmationBody(params: {
  headerLine: string;
  appointmentLine: string;
  serviceName: string;
  venuePhone: string | null;
}): string {
  const formattedContact = formatAuPhoneForSmsDisplay(params.venuePhone);
  const rawVenuePhone = String(params.venuePhone ?? "").trim();
  const contactPhone: string | null =
    formattedContact ?? (rawVenuePhone.length > 0 ? rawVenuePhone : null);
  const contactInstruction = contactPhone
    ? `Call or Text to ${contactPhone}`
    : "Call or Text your Haeyoom location";

  return (
    `${params.headerLine}\n\n` +
    `Appointment: \n` +
    `${params.appointmentLine} \n` +
    `Service: ${params.serviceName}\n\n` +
    `To Change or Cancel: \n` +
    `${contactInstruction}`
  );
}

const supabaseUrl = Deno.env.get("SUPABASE_URL");
const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

if (!supabaseUrl || !supabaseServiceKey) {
  throw new Error("Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY environment variables");
}

const supabase = createClient(supabaseUrl, supabaseServiceKey, {
  auth: { persistSession: false },
});

const MOBILE_MESSAGE_API_USERNAME = Deno.env.get("MOBILE_MESSAGE_API_USERNAME") ?? "";
const MOBILE_MESSAGE_API_PASSWORD = Deno.env.get("MOBILE_MESSAGE_API_PASSWORD") ?? "";
const MOBILE_MESSAGE_SENDER_ID = Deno.env.get("MOBILE_MESSAGE_SENDER_ID") ?? "";

function toAuMobileRecipient(phone: string): string {
  const digits = phone.replace(/\D/g, "");
  if (digits.startsWith("61") && digits.length === 11) {
    return `0${digits.slice(2)}`;
  }
  if (digits.startsWith("0") && digits.length === 10) {
    return digits;
  }
  return phone.trim();
}

async function sendSmsViaMobileMessage(to: string, body: string): Promise<Response> {
  const basicAuth = btoa(`${MOBILE_MESSAGE_API_USERNAME}:${MOBILE_MESSAGE_API_PASSWORD}`);
  return await fetch("https://api.mobilemessage.com.au/v1/messages", {
    method: "POST",
    headers: {
      Authorization: `Basic ${basicAuth}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      messages: [
        {
          to: toAuMobileRecipient(to),
          message: body,
          sender: MOBILE_MESSAGE_SENDER_ID,
        },
      ],
    }),
  });
}

Deno.serve(async (req: Request) => {
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { "Content-Type": "application/json" },
    });
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
      status: 400,
      headers: { "Content-Type": "application/json" },
    });
  }

  const bookingIdRaw = (body as { booking_id?: unknown })?.booking_id;
  const bookingId =
    typeof bookingIdRaw === "number" && Number.isFinite(bookingIdRaw)
      ? bookingIdRaw
      : typeof bookingIdRaw === "string"
        ? Number.parseInt(bookingIdRaw, 10)
        : NaN;

  if (!Number.isFinite(bookingId) || bookingId <= 0) {
    return new Response(JSON.stringify({ error: "booking_id is required" }), {
      status: 400,
      headers: { "Content-Type": "application/json" },
    });
  }

  if (!MOBILE_MESSAGE_API_USERNAME || !MOBILE_MESSAGE_API_PASSWORD || !MOBILE_MESSAGE_SENDER_ID) {
    console.error("[booking-confirmation-sms] Mobile Message env missing");
    return new Response(JSON.stringify({ error: "SMS provider not configured" }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }

  try {
    const { data: booking, error } = await supabase
      .from("bookings")
      .select(
        `
      id,
      booking_date,
      booking_time,
      custom_service_name,
      service:service_id ( name, english_name ),
      customer:customer_id ( phone ),
      shop:shop_id ( name, phone )
    `,
      )
      .eq("id", bookingId)
      .maybeSingle();

    if (error) {
      console.error("[booking-confirmation-sms] load booking failed", error);
      return new Response(JSON.stringify({ error: "Failed to load booking" }), {
        status: 500,
        headers: { "Content-Type": "application/json" },
      });
    }

    if (!booking) {
      return new Response(JSON.stringify({ error: "Booking not found" }), {
        status: 404,
        headers: { "Content-Type": "application/json" },
      });
    }

    const phone = (booking.customer as { phone?: string | null } | null)?.phone;
    if (!phone || !isValidAuMobilePhone(phone)) {
      console.warn("[booking-confirmation-sms] skip: missing or invalid AU mobile", bookingId);
      return new Response(
        JSON.stringify({ ok: true, skipped: true, reason: "invalid_or_missing_phone" }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }

    const shopRow = booking.shop as { name?: string | null; phone?: string | null } | null;
    const headerLine = haeyoomSmsHeader(shopRow?.name);
    const shopLabelForLog = String(shopRow?.name ?? "").trim() || "Salon";
    const venuePhone =
      shopRow?.phone != null && String(shopRow.phone).trim() ? String(shopRow.phone).trim() : null;
    if (!venuePhone) {
      console.warn("[booking-confirmation-sms] shop phone missing for booking", bookingId, shopLabelForLog);
    }

    const svc = booking.service as { name?: string | null; english_name?: string | null } | null;
    const customForSms = stripPromoFromCustomServiceNameForConfirmationSms(
      (booking as { custom_service_name?: string | null }).custom_service_name,
    );
    const serviceName = stripPromoFromConfirmationSmsServiceLabel(
      smsServiceLabelEn(svc?.english_name, svc?.name, customForSms),
    );

    const appointmentLine = formatReminderAppointmentLine(
      booking.booking_date,
      booking.booking_time ?? "00:00:00",
    );

    const messageBody = buildBookingConfirmationBody({
      headerLine,
      appointmentLine,
      serviceName,
      venuePhone,
    });

    const smsRes = await sendSmsViaMobileMessage(phone, messageBody);
    if (!smsRes.ok) {
      const text = await smsRes.text();
      console.error("[booking-confirmation-sms] Mobile Message error:", smsRes.status, text);
      return new Response(JSON.stringify({ error: "Failed to send SMS", detail: text }), {
        status: 502,
        headers: { "Content-Type": "application/json" },
      });
    }

    const mmPayload = await smsRes.json().catch(() => null) as {
      results?: Array<{ message_id?: string }>;
    } | null;
    return new Response(
      JSON.stringify({
        ok: true,
        booking_id: bookingId,
        message_id: mmPayload?.results?.[0]?.message_id ?? null,
      }),
      { status: 200, headers: { "Content-Type": "application/json" } },
    );
  } catch (err) {
    console.error("[booking-confirmation-sms] unexpected error", err);
    return new Response(JSON.stringify({ error: "Internal error" }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }
});

/** Keep in sync with lib/public-booking-labels.ts and lib/booking-confirmation-sms.ts */
/** Exact phrase matches (after stripping card/cash suffixes and trimming). */
const SERVICE_NAME_KO_TO_EN: Record<string, string> = {
  여자커트: "Women's haircut",
  남자커트: "Men's haircut",
  여성커트: "Women's haircut",
  남성커트: "Men's haircut",
  커트: 'Haircut',
  베이직커트: 'Basic haircut',
  키즈커트: "Kids' haircut",
  앞머리커트: 'Bangs trim',
  드라이: 'Blow dry',
  스타일링: 'Styling',
  염색: 'Colour',
  컬러: 'Colour',
  블리치: 'Bleach',
  토닝: 'Toning',
  디지털펌: 'Digital perm',
  '디지털 펌': 'Digital perm',
  열펌: 'Hot perm',
  매직펌: 'Magic straight perm',
  매직: 'Magic straight',
  핫펌: 'Hot perm',
  클리닉: 'Treatment clinic',
  크리닉: 'Treatment clinic',
  두피클리닉: 'Scalp treatment',
  패키지: 'Package',
  기타: 'Other',
};

function stripPaymentSuffix(name: string): string {
  return name.replace(/\s*\(card\)\s*/gi, '').replace(/\s*\(cash\)\s*/gi, '').trim();
}

/** True if string contains Hangul syllables. */
function containsHangul(s: string): boolean {
  return /[\uAC00-\uD7AF]/.test(s);
}

/** True if label is suitable as English as-is (Latin letters, digits, common punctuation). */
function isMostlyLatinLabel(s: string): boolean {
  const hangul = s.replace(/[^\uAC00-\uD7AF]/g, '');
  if (hangul.length === 0) return true;
  const latin = s.replace(/[^a-zA-Z]/g, '');
  return latin.length > 0 && latin.length >= hangul.length;
}

/**
 * Translate catalog or custom service names for public English UI.
 */
export function translateServiceNameToEnglish(raw: string | null | undefined): string | null {
  if (!raw?.trim()) return null;
  const s = stripPaymentSuffix(raw);
  if (!s) return null;

  const compact = s.replace(/\s+/g, '');
  if (SERVICE_NAME_KO_TO_EN[compact]) return SERVICE_NAME_KO_TO_EN[compact];
  if (SERVICE_NAME_KO_TO_EN[s]) return SERVICE_NAME_KO_TO_EN[s];

  if (isMostlyLatinLabel(s)) return s;

  let out = s;

  const replacements: Array<[RegExp, string]> = [
    [/여자\s*/g, "Women's "],
    [/남자\s*/g, "Men's "],
    [/여성\s*/g, "Women's "],
    [/남성\s*/g, "Men's "],
    [/키즈\s*/g, "Kids' "],
    [/매직\s*/g, 'magic '],
    [/커트/g, 'haircut'],
    [/드라이/g, 'blow dry'],
    [/스타일링/g, 'styling'],
    [/염색/g, 'colour'],
    [/컬러/g, 'colour'],
    [/블리치/g, 'bleach'],
    [/토닝/g, 'toning'],
    [/펌/g, 'perm'],
    [/클리닉/g, 'clinic'],
    [/트리트먼트/g, 'treatment'],
    [/두피/g, 'scalp '],
  ];

  for (const [re, repl] of replacements) {
    out = out.replace(re, repl);
  }

  out = out.replace(/\s+/g, ' ').trim();
  if (!out) return null;

  const sentence = out.charAt(0).toUpperCase() + out.slice(1);
  return sentence;
}

/**
 * Catalog service: DB english_name wins; else translate Korean name.
 */
export function publicServiceLabelEn(
  englishName: string | null | undefined,
  catalogName: string | null | undefined,
  customName: string | null | undefined,
): string | null {
  const fromDb = englishName?.trim();
  if (fromDb) return fromDb;

  const custom = customName?.trim();
  if (custom) {
    const t = translateServiceNameToEnglish(custom);
    if (t && !containsHangul(t)) return t;
    if (t && containsHangul(t)) return 'Hair service';
    if (!containsHangul(custom)) return custom;
  }

  const catalog = catalogName?.trim();
  if (catalog) {
    const t = translateServiceNameToEnglish(catalog);
    if (t && !containsHangul(t)) return t;
    if (t && containsHangul(t)) return 'Hair service';
    const stripped = stripPaymentSuffix(catalog);
    if (!containsHangul(stripped)) return stripped;
  }

  return 'Hair service';
}

/**
 * Stylist: english_name from staff profile; Latin-only name as fallback; otherwise generic English.
 */
export function publicStylistLabelEn(
  englishName: string | null | undefined,
  name: string | null | undefined,
): string {
  const en = englishName?.trim();
  if (en) return en;
  const n = name?.trim();
  if (n && !containsHangul(n)) return n;
  return 'Your stylist';
}

/** SMS: always English service line (DB english_name wins, else translate Ko). */
export function smsServiceLabelEn(
  englishName: string | null | undefined,
  catalogName: string | null | undefined,
  customName: string | null | undefined,
): string {
  return publicServiceLabelEn(englishName, catalogName, customName) ?? 'Hair service';
}

/** SMS header; Korean branch names become neutral English. */
export function haeyoomSmsHeader(shopName: string | null | undefined): string {
  const t = String(shopName ?? '').trim();
  if (!t) return 'Haeyoom Salon';
  if (containsHangul(t)) return 'Haeyoom Salon';

  // Comment: DB shop names may already include "HAEYOOM" / "Haeyoom" — avoid "Haeyoom Haeyoom …".
  const withoutBrand = t.replace(/^haeyoom\s*/i, '').trim();
  if (!withoutBrand) return 'Haeyoom Salon';
  return `Haeyoom ${withoutBrand}`;
}

/** Reminder Location line: known venues show store name only; hide Korean addresses. */
export function smsVenueLocationForReminder(
  location: string | null | undefined,
  shopName?: string | null | undefined,
): string {
  const haystack = `${String(location ?? '')} ${String(shopName ?? '')}`.trim().toLowerCase();
  if (haystack.includes('meadowbank')) return 'Meadowbank Store';
  if (haystack.includes('haymarket')) return 'Haymarket Store';

  const t = String(location ?? '').trim();
  if (!t) return 'Haeyoom salon';
  if (containsHangul(t)) return 'Your Haeyoom salon';
  return t;
}

/** Promo segments in comma-separated custom_service_name (pricing only, not for guest SMS). */
const CONFIRMATION_SMS_EXCLUDED_SERVICE_SEGMENT = /^website\s+exclusive\s*-\s*20\s*%?\s*off$/i;

function isExcludedConfirmationSmsServiceSegment(segment: string): boolean {
  const t = segment.trim();
  if (!t) return true;
  return CONFIRMATION_SMS_EXCLUDED_SERVICE_SEGMENT.test(t);
}

export function stripPromoFromCustomServiceNameForConfirmationSms(
  customName: string | null | undefined,
): string | null {
  const raw = String(customName ?? '').trim();
  if (!raw) return null;
  const parts = raw.split(',').map((p) => p.trim()).filter(Boolean);
  const kept = parts.filter((p) => !isExcludedConfirmationSmsServiceSegment(p));
  if (kept.length === 0) return null;
  return kept.join(', ');
}

export function stripPromoFromConfirmationSmsServiceLabel(label: string): string {
  const raw = String(label ?? '').trim();
  if (!raw) return raw;
  const parts = raw.split(',').map((p) => p.trim()).filter(Boolean);
  const kept = parts.filter((p) => !isExcludedConfirmationSmsServiceSegment(p));
  if (kept.length > 0) return kept.join(', ');
  return 'Hair service';
}
